<script setup lang="ts">
import {onMounted,ref} from 'vue';import type {RequestFn} from './media';import {date} from './lib';import AccountDeletion from './AccountDeletion.vue';
const props=defineProps<{request:RequestFn}>();const rows=ref<Record<string,any>[]>([]),scopes=ref<Record<string,string>>({}),editing=ref<Record<string,any>|null>(null),busy=ref(false),error=ref(''),notice=ref(''),deleted=ref(false),deleting=ref<Record<string,any>|null>(null);
async function load(){const d=await props.request('admin/administrators'+(deleted.value?'?deleted=1':''));rows.value=d.items;scopes.value=d.scopes}
function edit(row?:Record<string,any>){error.value='';editing.value=row?{id:row.id,version:row.admin_version,email:row.email,name:row.name,password:'',password_confirm:'',enabled:row.status==='active',scopes:[...row.admin_scopes]}:{email:'',name:'',password:'',password_confirm:'',enabled:true,scopes:['support']}}
async function save(){const e=editing.value;if(!e)return;busy.value=true;error.value='';try{if(e.password!==e.password_confirm)throw new Error('两次输入的密码不一致');await props.request('admin/administrators',e.id?'PUT':'POST',e);editing.value=null;await load();notice.value='副管理员已保存；权限变更会注销其已有登录会话。'}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
onMounted(()=>load().catch(e=>error.value=String(e)));
</script>
<template><div v-if="error" class="alert error">{{error}}</div><div v-if="notice" class="alert">{{notice}}</div><div class="section-head team-heading"><p class="muted">主管理员保留站点密钥、版本更新与管理员管理；副管理员仅可使用勾选的功能。</p><label class="multi"><input type="checkbox" v-model="deleted" @change="load">显示已删除副管理员</label><button class="primary" @click="edit()">＋ 添加副管理员</button></div><section class="panel"><div v-for="r in rows" :key="r.id" class="list-row team-row"><div><strong>{{r.name}} <span class="badge">{{r.is_owner?'主管理员':'副管理员'}}</span></strong><small>{{r.email}}</small><small>{{r.is_owner?'全部权限':r.admin_scopes.map((s:string)=>scopes[s]||s).join('、')}}</small><small>创建于 {{date(r.created_at)}}</small></div><span class="badge">{{r.deleted_at?'已删除':r.status==='active'?'已启用':'已停用'}}</span><div class="actions" v-if="!r.is_owner"><button v-if="!r.deleted_at" @click="edit(r)">编辑权限</button><button @click="deleting=r">{{r.deleted_at?'恢复':'删除副管理员'}}</button></div></div></section><AccountDeletion v-if="deleting" :request="request" :target="deleting" kind="administrators" @close="deleting=null" @changed="(message:string)=>{deleting=null;notice=message;void load()}"/><div v-if="editing" class="modal-backdrop" @click.self="editing=null"><form class="modal" role="dialog" aria-modal="true" aria-label="副管理员设置" @submit.prevent="save"><div class="section-head"><h2>{{editing.id?'编辑副管理员':'添加副管理员'}}</h2><button type="button" @click="editing=null" aria-label="关闭">×</button></div><div v-if="error" class="alert error">{{error}}</div><div class="fields"><label>名称<input v-model="editing.name" required maxlength="80"></label><label>登录邮箱<input v-model="editing.email" type="email" required :readonly="!!editing.id"></label><label>{{editing.id?'重设密码（留空保持）':'初始密码'}}<input v-model="editing.password" type="password" :required="!editing.id" minlength="12" maxlength="256" autocomplete="new-password"></label><label>再次输入密码<input v-model="editing.password_confirm" type="password" :required="!!editing.password" minlength="12" maxlength="256" autocomplete="new-password"></label></div><p v-if="editing.password_confirm&&editing.password!==editing.password_confirm" class="alert error">两次输入的密码不一致</p><h3>可操作功能</h3><div class="fields permission-grid"><label v-for="(name,id) in scopes" :key="id" class="multi"><input type="checkbox" v-model="editing.scopes" :value="id" @change="id==='delete_customers'&&editing.scopes.includes(id)&&!editing.scopes.includes('customers')&&editing.scopes.push('customers')">{{name}}</label></div><label class="multi"><input type="checkbox" v-model="editing.enabled">允许登录</label><div class="modal-actions"><button type="button" @click="editing=null">取消</button><button class="primary" :disabled="busy||!editing.scopes.length||editing.password!==editing.password_confirm">保存</button></div></form></div></template>

<style scoped>
.team-heading{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center}.team-heading>p{grid-column:1/-1;max-width:800px}.team-heading .multi{margin:0}.team-heading>button{white-space:nowrap}.team-row{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(220px,auto);gap:20px;align-items:center}.team-row>div{flex:initial}.team-row>.actions{justify-content:flex-end}.team-row strong{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.team-row small{line-height:1.8}.permission-grid{gap:10px 20px;margin:16px 0 22px}.permission-grid .multi{display:grid;grid-template-columns:18px minmax(0,1fr);align-items:center;gap:10px;margin:0;padding:12px;border:1px solid #e6ebf2;border-radius:8px;min-height:48px}@media(max-width:1000px){.team-row{grid-template-columns:minmax(0,1fr) auto}.team-row>.actions{grid-column:1/-1;justify-content:flex-start}}@media(max-width:600px){.team-heading{grid-template-columns:1fr}.team-heading>button{margin-left:0;justify-self:stretch}.team-row{gap:10px}.team-row>.actions>button{flex:1}.permission-grid{grid-template-columns:1fr}}
</style>
